CREATE OR REPLACE VIEW "public"."quiz_quality_7d" AS
 SELECT "difficulty",
    "count"(*) AS "total",
    "sum"(
        CASE
            WHEN "judge_ok" THEN 1
            ELSE 0
        END) AS "passed",
    "round"(((100.0 * ("sum"(
        CASE
            WHEN "judge_ok" THEN 1
            ELSE 0
        END))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pass_pct",
    "sum"(
        CASE
            WHEN "was_retried" THEN 1
            ELSE 0
        END) AS "retried"
   FROM "public"."quiz_quality_log"
  WHERE ("logged_at" > ("now"() - '7 days'::interval))
  GROUP BY "difficulty"
  ORDER BY "difficulty";


ALTER VIEW "public"."quiz_quality_7d" OWNER TO "postgres";


