    "period_start" "date" NOT NULL,
    "input_tokens" bigint DEFAULT 0,
    "output_tokens" bigint DEFAULT 0,
    "estimated_cost_cents" double precision DEFAULT 0,
    "message_count" integer DEFAULT 0,
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "cached_input_tokens" bigint DEFAULT 0
);


ALTER TABLE "public"."token_usage" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."usage_by_interaction" (
    "uid" "text" NOT NULL,
    "period_start" "date" NOT NULL,
    "interaction_type" "text" NOT NULL,
    "input_tokens" bigint DEFAULT 0 NOT NULL,
    "output_tokens" bigint DEFAULT 0 NOT NULL,
    "cached_input_tokens" bigint DEFAULT 0 NOT NULL,
    "estimated_cost_cents" double precision DEFAULT 0 NOT NULL,
    "request_count" integer DEFAULT 0 NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."usage_by_interaction" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."user_interests" (
    "uid" "text" NOT NULL,
    "topics" "text"[] DEFAULT '{}'::"text"[],
    "age_group" "text" DEFAULT 'all'::"text",
    "last_updated" timestamp with time zone DEFAULT "now"()
);


ALTER TABLE "public"."user_interests" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."user_progress" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "uid" "text",
    "journey_id" "text",
    "step_id" "text" NOT NULL,
    "completed_at" timestamp with time zone DEFAULT "now"()
);


ALTER TABLE "public"."user_progress" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."users" (
    "uid" "text" NOT NULL,
    "email" "text",
    "display_name" "text",
    "photo_url" "text",
    "onboarding_done" boolean DEFAULT false,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "streak_days" integer DEFAULT 0,
    "last_active_date" "date",
    "is_admin" boolean DEFAULT false,
    "birth_year" smallint,
    "age_group_flag" "text" DEFAULT 'adult'::"text",
    "account_status" "text" DEFAULT 'active'::"text",
    "consent_given_at" timestamp with time zone,
    "consent_version" "text" DEFAULT '1.0'::"text",
    "profession" "text",
    "role" "text" DEFAULT 'learner'::"text" NOT NULL,
    "birth_month" smallint,
    "jurisdiction" "text",
    "paused" boolean DEFAULT false NOT NULL,
    CONSTRAINT "users_birth_month_check" CHECK ((("birth_month" >= 1) AND ("birth_month" <= 12)))
);


ALTER TABLE "public"."users" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."visual_assets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "vlo_id" "uuid" NOT NULL,
    "asset_type" "text" NOT NULL,
    "storage_key" "text",
    "external_url" "text",
    "source_type" "text",
    "source_name" "text",
    "license_type" "text",
    "license_url" "text",
    "attribution" "text",
    "commercial_use_allowed" boolean,
    "modification_allowed" boolean,
    "width" integer,
    "height" integer,
    "duration_ms" integer,
    "file_size_bytes" bigint,
    "checksum" "text",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "visual_assets_asset_type_check" CHECK (("asset_type" = ANY (ARRAY['svg'::"text", 'png'::"text", 'jpg'::"text", 'webp'::"text", 'webm'::"text", 'mp4'::"text", 'gif'::"text", 'interactive'::"text", 'external_embed'::"text"]))),
    CONSTRAINT "visual_assets_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'validating'::"text", 'active'::"text", 'blocked'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."visual_assets" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."visual_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "uid" "text",
    "journey_id" "text",
    "step_id" "text",
    "vlo_id" "uuid",
    "session_id" "text",
    "event_type" "text" NOT NULL,
    "event_data" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "visual_events_event_type_check" CHECK (("event_type" = ANY (ARRAY['visual_impression'::"text", 'visual_started'::"text", 'visual_completed'::"text", 'visual_replayed'::"text", 'visual_skipped'::"text", 'visual_interaction'::"text", 'visual_error'::"text"])))
);


ALTER TABLE "public"."visual_events" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."visual_learning_objects" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "concept_key" "text" NOT NULL,
    "learning_objective_hash" "text" NOT NULL,
    "grade_band" "text" NOT NULL,
    "modality" "text" NOT NULL,
    "pedagogical_role" "text" NOT NULL,
    "renderer_type" "text",
    "recipe" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "content_hash" "text" NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "effectiveness_score" numeric,
    "reuse_count" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "vlo_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'queued'::"text", 'rendering'::"text", 'validating'::"text", 'active'::"text", 'deprecated'::"text", 'failed'::"text", 'blocked'::"text"])))
);


ALTER TABLE "public"."visual_learning_objects" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."visual_plans" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "journey_id" "text" NOT NULL,
    "step_id" "text" NOT NULL,
    "concept_key" "text" NOT NULL,
    "plan" "jsonb" NOT NULL,
    "planner_model" "text",
    "planner_prompt_version" integer NOT NULL,
    "estimated_cost_usd" numeric,
    "selected_strategy" "text",
    "execution_status" "text" DEFAULT 'planned'::"text" NOT NULL,
    "vlo_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "visual_plans_execution_status_check" CHECK (("execution_status" = ANY (ARRAY['planned'::"text", 'queued'::"text", 'executing'::"text", 'ready'::"text", 'failed'::"text", 'skipped'::"text"])))
);


ALTER TABLE "public"."visual_plans" OWNER TO "postgres";


